function buildChapterNodes(chapterNumber, rows) {
  return rows.map(([slug, title, section, type, level, summary, formula, variables, conditions, pitfalls, problemApproach, keywords, prerequisites = [], simulationId]) => ({
    id: `c${chapterNumber}-${slug}`,
    title,
    chapterId: `ch-${chapterNumber}`,
    section,
    type,
    level,
    summary,
    formula,
    variables,
    conditions,
    prerequisites,
    pitfalls,
    problemApproach,
    keywords,
    ...(simulationId ? { simulationId } : {}),
  }));
}

